                if summary.get("player_beer_barrels", 0) == 0:
                    score = 210.0
                elif summary.get("player_beer_barrels", 0) >= 2:
                    score = 70.0
                else:
                    score = 140.0
        elif ind in ("cotton", "goods", "pottery"):
            if ind == "pottery":
                score = 160.0
            elif ind == "cotton":
                score = 140.0 if lvl >= 2 else 90.0
            elif ind == "goods":
                score = 130.0 if lvl >= 2 else 70.0
            if era == "canal" and lvl >= 2:
                score += 35.0
            if summary.get("player_beer_barrels", 0) > 0 or summary.get("merchant_beer_barrels", 0) > 0:
                score += 25.0

    elif atype == "develop":
        inds = action.get("industries", [])
        score = 80.0
        if "goods" in inds:
            score += 35.0
        if "cotton" in inds:
            score += 25.0
        if "iron" in inds:
            score += 20.0
