            if turn <= 3:
                score += 40.0
            elif turn <= 6:
                score += 15.0
            else:
                score -= 50.0

    elif atype == "loan":
        if era == "canal":
            if money <= 6 and turn <= 6:
                score = 175.0
            elif money <= 10 and turn <= 5:
                score = 90.0
            elif money >= 16:
                score = -150.0
            elif turn >= 8:
                score = -400.0
        else:
            if money <= 12 and turn <= 4:
                score = 170.0
            elif money >= 18:
                score = -150.0
            elif turn >= 7:
                score = -600.0

    elif atype == "scout":
        score = -50.0
    elif atype == "pass":
        score = -1000.0

    return score

ranked = sorted([(score_action(a, state, summary), a["action_id"], a["action_type"], a.get("description")) for a in legal["actions"]], reverse=True)
