#!/usr/bin/env python3
"""Online Brass: Birmingham Controller vs Mautoma.

Plays a complete 20-round match (Canal Era + Rail Era) via the local daemon,
evaluating legal macro-actions to maximize Victory Points and defeat Mautoma.
"""

from __future__ import annotations

import json
import sys
import time
import urllib.error
import urllib.request
from collections import deque
from typing import Any, Dict, List, Optional, Set, Tuple

DAEMON_URL = "http://127.0.0.1:18765"
DENSE_CITIES = {
    "birmingham", "wolverhampton", "walsall", "dudley", "coventry", "stoke", "derby"
}
CORE_CITIES = {"birmingham", "wolverhampton", "coalbrookdale", "walsall"}
MERCHANT_PORTS = {"shrewsbury", "gloucester", "oxford"}


def http_get(path: str, timeout: float = 10.0) -> Dict[str, Any]:
    url = f"{DAEMON_URL}{path}"
    req = urllib.request.Request(url, method="GET")
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        return json.loads(resp.read().decode("utf-8"))


def http_post(path: str, body: Dict[str, Any], timeout: float = 30.0) -> Dict[str, Any]:
    url = f"{DAEMON_URL}{path}"
    data = json.dumps(body).encode("utf-8")
    req = urllib.request.Request(
        url, data=data, headers={"Content-Type": "application/json"}, method="POST"
    )
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        return json.loads(resp.read().decode("utf-8"))


def parse_link_endpoints(lid: str) -> List[Tuple[str, str]]:
    parts = lid.split("-")
    if len(parts) == 2:
        return [(parts[0], parts[1])]
    elif len(parts) == 3:
        return [(parts[0], parts[1]), (parts[1], parts[2]), (parts[0], parts[2])]
    return []


def is_connected_to_merchant(city: str, merchant_id: str, links: Dict[str, Any]) -> bool:
    if city == merchant_id:
        return True
    adj: Dict[str, Set[str]] = {}
    for lid in links.keys():
        for u, v in parse_link_endpoints(lid):
            adj.setdefault(u, set()).add(v)
            adj.setdefault(v, set()).add(u)

    visited: Set[str] = set()
    queue = deque([city])
    while queue:
        curr = queue.popleft()
        if curr == merchant_id:
            return True
        if curr in visited:
            continue
        visited.add(curr)
        for nbr in adj.get(curr, set()):
            if nbr not in visited:
                queue.append(nbr)
    return False


def count_dots_at_city(city: str, board: Dict[str, Any]) -> int:
    slots = board.get(city) or []
    dots = 0
    for tile in slots:
        if tile and isinstance(tile, dict):
            if tile.get("flipped") or tile.get("is_flipped") or tile.get("state") == "flipped":
                dots += tile.get("link_points", tile.get("link_dots", 1))
    return dots


def card_keep_penalty(action: Dict[str, Any], state: Dict[str, Any]) -> float:
    card_slot = action.get("card_slot")
    hand = state.get("hand") or []
    if card_slot is None or card_slot >= len(hand) or card_slot < 0:
        return 0.0
    card = hand[card_slot]
    kind = card.get("kind")
    city = card.get("city")

    # If duplicate in hand, safe to discard one
    dups = sum(
        1 for c in hand if c.get("city") == city and c.get("kind") == kind
    )
    if dups > 1:
        return 0.0

    if city in ("birmingham", "wolverhampton", "coalbrookdale"):
        return -5.0
    if city in ("walsall", "dudley", "coventry"):
        return -2.5
    return 0.0


def score_action(action: Dict[str, Any], state: Dict[str, Any], summary: Dict[str, Any]) -> float:
    atype = action.get("action_type")
    score = 0.0
    era = state.get("era", "canal")
    turn = state.get("turn", 1)
    money = state.get("money", 0)
    iron_cubes = state.get("iron_cubes", 0)
    coal_cubes = state.get("coal_cubes", 0)
    empty_iron = max(0, 14 - iron_cubes)
    empty_coal = max(0, 14 - coal_cubes)
    links = state.get("links") or {}
    board = state.get("board") or {}

    player_beer = summary.get("player_beer_barrels", 0)
    merchant_beer = summary.get("merchant_beer_barrels", 0)
    any_beer = (player_beer > 0) or (merchant_beer > 0)

    # 1. SELL
    if atype == "sell":
        score = 320.0
        sales = action.get("sales") or []
        score += 60.0 * max(1, len(sales))
        for sale in sales:
            ind = sale.get("industry") if isinstance(sale, dict) else str(sale)
            if ind == "pottery":
                score += 60.0
            elif ind == "cotton":
                score += 40.0
            elif ind == "goods":
                score += 35.0
        if player_beer > 0:
            score += 45.0  # flips our brewery
        elif merchant_beer > 0:
            score += 25.0  # free merchant beer
        if era == "canal" and turn >= 8:
            score += 120.0
        elif era == "rail" and turn >= 8:
            score += 180.0

    # 2. NETWORK
    elif atype == "network":
        is_double = action.get("is_double_rail", False)
        if era == "rail":
            if is_double:
                score = 290.0
                if player_beer > 0:
                    score += 50.0  # consumes beer and flips our brewery!
                link_ids = action.get("link_ids") or []
                for lid in link_ids:
                    for u, v in parse_link_endpoints(lid):
                        if u in DENSE_CITIES:
                            score += 15.0
                        if v in DENSE_CITIES:
                            score += 15.0
                        score += 12.0 * (count_dots_at_city(u, board) + count_dots_at_city(v, board))
            else:
                score = 110.0
                lid = action.get("link_id", "")
                for u, v in parse_link_endpoints(lid):
                    if u in DENSE_CITIES:
                        score += 12.0
                    if v in DENSE_CITIES:
                        score += 12.0
                    score += 10.0 * (count_dots_at_city(u, board) + count_dots_at_city(v, board))
        else:  # Canal Era
            score = 65.0
            lid = action.get("link_id", "")
            for u, v in parse_link_endpoints(lid):
                if u in MERCHANT_PORTS or v in MERCHANT_PORTS:
                    score += 90.0  # connects to merchant port!
                if u in DENSE_CITIES:
                    score += 25.0
                if v in DENSE_CITIES:
                    score += 25.0
                score += 15.0 * (count_dots_at_city(u, board) + count_dots_at_city(v, board))
            p_links = summary.get("player_link_count", 0)
            if p_links >= 5:
                score -= 20.0 * (p_links - 4)

    # 3. BUILD
    elif atype == "build":
        ind = action.get("industry")
        lvl = action.get("level", 1)
        city = action.get("city", "")

        if ind == "iron":
            if empty_iron >= 4:
                score = 280.0  # auto-flips + £14 profit!
            elif empty_iron >= 2:
                score = 190.0
            else:
                score = 120.0
            if lvl >= 2:
                score += 35.0

        elif ind == "coal":
            # Check if city is connected to a merchant port (market coal connection)
            connected_to_market = any(
                is_connected_to_merchant(city, m, links) for m in MERCHANT_PORTS
            )
            if connected_to_market and empty_coal >= lvl:
                score = 240.0  # auto-flips!
            elif connected_to_market and empty_coal > 0:
                score = 175.0
            else:
                if era == "rail":
                    if summary.get("player_remaining_mine_cubes", 0) == 0:
                        score = 195.0
                    else:
                        score = 130.0
                else:
                    score = 135.0
            if lvl >= 2:
                score += 30.0

        elif ind == "brewery":
            if era == "canal":
                if summary.get("player_unflipped_count", 0) > 0:
                    score = 230.0  # urgently need beer to sell!
                else:
                    score = 100.0
            else:
                if player_beer == 0:
                    score = 235.0  # beer enables double rails!
                elif player_beer == 1:
                    score = 160.0
                else:
                    score = 75.0
            if lvl >= 2:
                score += 25.0

        elif ind in ("cotton", "goods", "pottery"):
            connected_shrewsbury = is_connected_to_merchant(city, "shrewsbury", links)
            connected_gloucester = is_connected_to_merchant(city, "gloucester", links)
            connected_oxford = is_connected_to_merchant(city, "oxford", links)

            if ind == "cotton":
                can_sell = connected_shrewsbury or connected_oxford
                if can_sell and any_beer:
                    score = 220.0 if lvl >= 2 else 150.0
                elif can_sell:
                    score = 140.0 if lvl >= 2 else 100.0
                else:
                    if era == "canal" and turn >= 7:
                        score = -40.0
                    else:
                        score = 75.0
                if era == "canal" and lvl >= 2:
                    score += 45.0

            elif ind == "goods":
                can_sell = connected_gloucester or connected_oxford
                if can_sell and any_beer:
                    score = 210.0 if lvl >= 2 else 140.0
                elif can_sell:
                    score = 135.0 if lvl >= 2 else 95.0
                else:
                    if era == "canal" and turn >= 7:
                        score = -40.0
                    else:
                        score = 70.0
                if era == "canal" and lvl >= 2:
                    score += 40.0

            elif ind == "pottery":
                can_sell = connected_oxford
                if can_sell and any_beer:
                    score = 230.0
                elif can_sell:
                    score = 140.0
                else:
                    score = 110.0

    # 4. DEVELOP
    elif atype == "develop":
        inds = action.get("industries") or []
        score = 80.0
        if "goods" in inds:
            score += 45.0  # unlocks L2 Goods (survives Canal!)
        if "cotton" in inds:
            score += 35.0  # unlocks L2 Cotton (survives Canal!)
        if "iron" in inds:
            score += 25.0  # unlocks L2 Iron
        if "brewery" in inds:
            score += 15.0

        if era == "canal":
            if turn <= 3:
                score += 55.0
            elif turn <= 6:
                score += 15.0
            else:
                score -= 60.0
        else:
            score = 40.0

    # 5. LOAN
    elif atype == "loan":
        if era == "canal":
            if money <= 6 and turn <= 6:
                score = 185.0
            elif money <= 10 and turn <= 5:
                score = 110.0
            elif money >= 16:
                score = -200.0
            elif turn >= 8:
                score = -500.0
        else:
            if money <= 12 and turn <= 4:
                score = 190.0  # unlocks double rail!
            elif money >= 18:
                score = -200.0
            elif turn >= 7:
                score = -700.0

    # 6. SCOUT & PASS
    elif atype == "scout":
        score = -50.0
    elif atype == "pass":
        score = -1000.0

    # Card discard preference penalty
    score += card_keep_penalty(action, state)

    return score


def play_full_match() -> None:
    print("=" * 70)
    print("STARTING BRASS: BIRMINGHAM ONLINE CONTROLLER MATCH VS MAUTOMA")
    print("=" * 70)

    start_time = time.time()
    step_count = 0

    while True:
        status_res = http_get("/status")
        if not status_res.get("ok"):
            print(f"Error fetching status: {status_res.get('error')}", file=sys.stderr)
            break

        state = status_res.get("state", {})
        summary = status_res.get("board_summary", {})
        preview = status_res.get("harbor_score_preview", {})

        if state.get("game_over"):
            print("\n>>> GAME OVER DETECTED! Match complete.")
            break

        legal_res = http_get("/legal")
        if not legal_res.get("ok"):
            print(f"Error fetching legal actions: {legal_res.get('error')}", file=sys.stderr)
            break

        actions = legal_res.get("actions", [])
        if not actions:
            print("No legal actions returned but game_over is False!", file=sys.stderr)
            break

        # Score and rank all candidate legal actions
        scored_actions = []
        for a in actions:
            sc = score_action(a, state, summary)
            scored_actions.append((sc, a))

        scored_actions.sort(key=lambda x: x[0], reverse=True)
        best_score, best_action = scored_actions[0]

        step_count += 1
        aid = best_action["action_id"]
        atype = best_action.get("action_type")
        desc = best_action.get("description", "")
        era = state.get("era")
        turn = state.get("turn")
        money = state.get("money")
        y_vp = preview.get("your_vp", 0)
        a_vp = preview.get("automa_vp", 0)

        print(
            f"Step #{step_count:2d} | Era {era:5s} Rd {turn:2d} | Cash £{money:2d} | "
            f"VP You {y_vp:3d} vs Automa {a_vp:3d} | "
            f"Action [{aid:2d}] {atype:7s} (score {best_score:5.1f}): {desc}"
        )

        # Execute action
        play_res = http_post("/play", {"action_id": aid})
        if not play_res.get("ok"):
            print(f"ERROR playing action {aid}: {play_res.get('error')}", file=sys.stderr)
            break

        if play_res.get("game_over"):
            print("\n>>> MATCH COMPLETED on executed step!")
            break

    elapsed = time.time() - start_time
    print("\n" + "=" * 70)
    print(f"MATCH SUMMARY ({elapsed:.2f}s elapsed, {step_count} macro-actions played)")
    print("=" * 70)

    final_status = http_get("/status")
    final_state = final_status.get("state", {})
    final_prev = final_status.get("harbor_score_preview", {})
    print(f"Game Over     : {final_state.get('game_over')}")
    print(f"Your VP       : {final_prev.get('your_vp')}")
    print(f"Mautoma VP    : {final_prev.get('automa_vp')}")
    print(f"VP Margin     : {final_prev.get('vp_margin')}")
    print(f"Won           : {final_prev.get('won')}")
    print(f"Harbor Reward : {final_prev.get('reward'):.6f}")
    print(f"Completion    : {final_prev.get('completion_score', 0):.4f}")
    print(f"VP Score      : {final_prev.get('vp_score', 0):.4f}")
    print(f"Competitive   : {final_prev.get('competitive_score', 0):.4f}")
    print("=" * 70)


if __name__ == "__main__":
    play_full_match()

